// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

namespace {

// logical dimensions for the 2D grid
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// tuning of memory layout (row-major: i is row, j is column)
struct tuning {
	DEFINE_PROTO_STRUCT(grid_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(std::size_t n, auto A, auto B) {
	// A, B: i x j (n x n)
	using namespace noarr;

	traverser(A, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (((num_t)i * (j + 2)) + (num_t)2) / (num_t)n;
		B[state] = (((num_t)i * (j + 3)) + (num_t)3) / (num_t)n;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(std::size_t tsteps, auto A, auto B) {
	// A, B: i x j (n x n)
	using namespace noarr;

	// full sizes
	auto ni = A | get_length<'i'>();
	auto nj = A | get_length<'j'>();

	// interior domain: i, j in [1, n-2]
	auto interior_i_len = ni - 2;
	auto interior_j_len = nj - 2;

	auto interior =
		noarr::slice<'i'>(1, interior_i_len) ^
		noarr::slice<'j'>(1, interior_j_len);

#pragma scop
	for (std::size_t t = 0; t < tsteps; t++) {
		// B := stencil(A)
		noarr::traverser(A, B)
			.order(interior)
			.template for_dims<'i'>([=](auto inner) {
				inner.for_each([=](auto state) {
					auto [i, j] = get_indices<'i', 'j'>(state);

					// neighbor states in A
					auto s_left  = noarr::idx<'i', 'j'>(i, j - 1);
					auto s_right = noarr::idx<'i', 'j'>(i, j + 1);
					auto s_down  = noarr::idx<'i', 'j'>(i + 1, j);
					auto s_up    = noarr::idx<'i', 'j'>(i - 1, j);

					B[state] = (num_t)0.2 * (
						A[state] +
						A[s_left] +
						A[s_right] +
						A[s_down] +
						A[s_up]
					);
				});
			});

		// A := stencil(B)
		noarr::traverser(A, B)
			.order(interior)
			.template for_dims<'i'>([=](auto inner) {
				inner.for_each([=](auto state) {
					auto [i, j] = get_indices<'i', 'j'>(state);

					// neighbor states in B
					auto s_left  = noarr::idx<'i', 'j'>(i, j - 1);
					auto s_right = noarr::idx<'i', 'j'>(i, j + 1);
					auto s_down  = noarr::idx<'i', 'j'>(i + 1, j);
					auto s_up    = noarr::idx<'i', 'j'>(i - 1, j);

					A[state] = (num_t)0.2 * (
						B[state] +
						B[s_left] +
						B[s_right] +
						B[s_down] +
						B[s_up]
					);
				});
			});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set logical lengths of the grid
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate bags for A and B with chosen layout
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);

	// initialize data
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_2d(tsteps, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE barrier)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

