#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// Layout: A[i][j], B[i][j] with j as the inner (contiguous) dimension,
	// matching the C row-major layout.
	DEFINE_PROTO_STRUCT(grid_layout, j_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(std::size_t n, auto A, auto B) {
	using namespace noarr;

	const num_t n_val = static_cast<num_t>(n);

	// A, B: i x j
	traverser(A, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (static_cast<num_t>(i) * static_cast<num_t>(j + 2) + static_cast<num_t>(2)) / n_val;
		B[state] = (static_cast<num_t>(i) * static_cast<num_t>(j + 3) + static_cast<num_t>(3)) / n_val;
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Work only on the interior: i, j in [1, n-2]
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2);

	const num_t c = SCALAR_VAL(0.2);

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First phase: B <- stencil(A)
		traverser(A, B)
			.order(interior)
			.for_each([=](auto state) {
				// state contains interior (i, j)
				const num_t sum =
					A[state] +
					A[noarr::neighbor<'j'>(state, -1)] + // A[i][j-1]
					A[noarr::neighbor<'j'>(state, +1)] + // A[i][j+1]
					A[noarr::neighbor<'i'>(state, +1)] + // A[i+1][j]
					A[noarr::neighbor<'i'>(state, -1)];  // A[i-1][j]

				B[state] = c * sum;
			});

		// Second phase: A <- stencil(B)
		traverser(A, B)
			.order(interior)
			.for_each([=](auto state) {
				const num_t sum =
					B[state] +
					B[noarr::neighbor<'j'>(state, -1)] + // B[i][j-1]
					B[noarr::neighbor<'j'>(state, +1)] + // B[i][j+1]
					B[noarr::neighbor<'i'>(state, +1)] + // B[i+1][j]
					B[noarr::neighbor<'i'>(state, -1)];  // B[i-1][j]

				A[state] = c * sum;
			});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// Set lengths for dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// Allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);

	// Initialize arrays
	init_array(n, A.get_ref(), B.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_jacobi_2d(tsteps, static_cast<int>(n), A.get_ref(), B.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

