#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// 2D layout: i is the outer dimension, j is the inner dimension
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// Array initialization
//
// C version:
//
// for (i = 0; i < n; i++)
//   for (j = 0; j < n; j++) {
//     A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
//     B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
//   }
void init_array(int n, auto A, auto B) {
	using namespace noarr;

	traverser(A, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = ((num_t)i * (j + 2) + (num_t)2) / (num_t)n;
		B[state] = ((num_t)i * (j + 3) + (num_t)3) / (num_t)n;
	});
}

// Main computational kernel
//
// C version:
//
// for (t = 0; t < _PB_TSTEPS; t++) {
//   for (i = 1; i < _PB_N - 1; i++)
//     for (j = 1; j < _PB_N - 1; j++)
//       B[i][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
//   for (i = 1; i < _PB_N - 1; i++)
//     for (j = 1; j < _PB_N - 1; j++)
//       A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
// }
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// Interior region: i, j in [1, n-1]
	auto ni = A | get_length<'i'>();
	auto nj = A | get_length<'j'>();

	auto interior =
		noarr::slice<'i'>(1, ni - 2) ^  // i = 1 .. ni-2
		noarr::slice<'j'>(1, nj - 2);  // j = 1 .. nj-2

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First sweep: update B from A on the interior
		noarr::traverser(A, B).order(interior).for_each([=](auto state) {
			// state contains global indices i, j within the interior
			auto center = A[state];
			auto left   = A[noarr::neighbor<'j'>(state, -1)];
			auto right  = A[noarr::neighbor<'j'>(state, +1)];
			auto up     = A[noarr::neighbor<'i'>(state, -1)];
			auto down   = A[noarr::neighbor<'i'>(state, +1)];

			B[state] = SCALAR_VAL(0.2) * (center + left + right + up + down);
		});

		// Second sweep: update A from B on the same interior
		noarr::traverser(A, B).order(interior).for_each([=](auto state) {
			auto center = B[state];
			auto left   = B[noarr::neighbor<'j'>(state, -1)];
			auto right  = B[noarr::neighbor<'j'>(state, +1)];
			auto up     = B[noarr::neighbor<'i'>(state, -1)];
			auto down   = B[noarr::neighbor<'i'>(state, +1)];

			A[state] = SCALAR_VAL(0.2) * (center + left + right + up + down);
		});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set lengths for i and j dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate bags for A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(static_cast<int>(n), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_2d(static_cast<int>(tsteps), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' so rows are printed contiguously
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
